sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    mfunction = g_form.getValue('u_mincident.u_rule_s_to_add_change_remove');
    g_form.setValue('u_mincident.u_rule_data.form-control', ' result');

    showCustomModal(myCallback);
}

function myCallback(result) {
    g_form.setValue('u_rule_data', result);
}

function showCustomModal(xCallback) {
    var modal = new GlideModal('custom_modal');
    modal.setTitle('Enter Your Data');

    // Define the HTML content with an input field
    modal.renderWithContent('<div style="padding: 20px;">' +
        '<input type="text" id="srcz" style="width:40%; margin-bottom:10px;" />' +
        '<input type="text" id="srcip" style="width:40%; margin-bottom:10px;" />' +
        '<input type="text" id="dstz" style="width:40%; margin-bottom:10px;" />' +
        '<input type="text" id="dstip" style="width:40%; margin-bottom:10px;" />' +
        '<button id="submitBtn">Submit</button>' +
        '</div>');

    // Add a click listener to the Submit button to send data back
    setTimeout(function() {
        var submitButton = document.getElementById('submitBtn');
        if (submitButton) {
            submitButton.onclick = function() {
                var srcz = document.getElementById('srcz').value;
                var srcip = document.getElementById('srcip').value;
                var dstz = document.getElementById('dstz').value;
                var dstip = document.getElementById('dstip').value;
                var userInput =
                    '<table id="md_table_2" style="width:100%;">' +
                    '<tr>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Sel</th>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Src. zone</th>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Src. zone</th>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Sel</th>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Src. IP/Netmask/FQDN</th>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Dest. zone</th>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Dest. zone</th>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Sel</th>' +
                    '<th style="border: 1px solid black;padding: 4px;text-align: left;">Dst. IP/Netmask/FQDN</th>' +
                    '</tr>' +
                    '<tr>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">S zone 1</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">S zone 2</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">IP</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">192.168.1.2</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">D zone 1</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">D zone 2</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">IP</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">192.168.1.4</td>' +
                    '</tr>' +
                    '<tr>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">S zone 1</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">S zone 2</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">IP</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">192.168.1.3</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">D zone 1</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">D zone 2</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">IP</td>' +
                    '<td style="border: 1px solid black;padding: 4px;text-align: left;">192.168.1.5</td>' +
                    '</tr>' +
                    '</table>';
                xCallback(userInput);
                modal.close();
            };
        }
    }, 500);
}
